#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class DspHarmonicsTask final {
public:enum class Stage{Invalidate,FullScale,Address,FirstWord,Divisor,Dividend,DivideHigh,RetainHigh,CopyRemainder,ClearRemainder,DivideLow,RetainLow,NextWord,Increment,Compare,Repeat,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned divisor()const{return divisor_;}uint32_t word()const{return stage_==Stage::FirstWord?0x7fffff:unsigned(high_)<<8;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Invalidate:case Stage::FirstWord:case Stage::NextWord:return c.call;case Stage::FullScale:case Stage::Dividend:return 9;case Stage::Address:case Stage::Divisor:case Stage::Compare:return 6;case Stage::DivideHigh:case Stage::DivideLow:return 23;case Stage::Return:return c.ret;default:return 3;}}
 unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Invalidate:case Stage::FirstWord:case Stage::NextWord:waiting_=true;break;case Stage::Divisor:divisor_=2;break;case Stage::DivideHigh:high_=uint16_t(0x8000/divisor_);break;case Stage::Increment:++divisor_;break;case Stage::Repeat:if(divisor_<=1024)next=Stage::Dividend;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Invalidate;unsigned divisor_=0;uint16_t high_=0;bool waiting_=false;};
class DspGlobalsTask final {
public:enum class Stage{Harmonics,Count,WriteCount,InitializeVoices,ResetCursor,Clear,WritePart,WriteLatch,WriteSlot,WriteFlags,MirrorSlot,Return,Complete};enum class Write{Count,Part,Latch,Slot,Flags};enum class Child{Harmonics,Voices,Cursor,Mirror};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Harmonics:return c.shortCall;case Stage::InitializeVoices:case Stage::ResetCursor:case Stage::MirrorSlot:return c.call;case Stage::WriteCount:case Stage::WritePart:case Stage::WriteLatch:case Stage::WriteSlot:case Stage::WriteFlags:return 9+c.write;case Stage::Return:return c.ret;default:return 3;}}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::Harmonics:case Stage::InitializeVoices:case Stage::ResetCursor:case Stage::MirrorSlot:waiting_=true;break;case Stage::WriteCount:write(Write::Count,8);break;case Stage::WritePart:write(Write::Part,0);break;case Stage::WriteLatch:write(Write::Latch,0);break;case Stage::WriteSlot:write(Write::Slot,0);break;case Stage::WriteFlags:write(Write::Flags,0);break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Harmonics;bool waiting_=false;};
class DspCursorResetTask final {
public:enum class Stage{Clear,Write,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned nextClocks(const FlashCredits&c)const{return complete()?0:stage_==Stage::Write?9+c.write:stage_==Stage::Return?c.ret:3;}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::Write)write(0);stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Clear;};
}
